using Beep.OilandGas.Models.Data.ProductionAccounting;
using System.Text.Json;
using TheTechIdea.Data.OilGas;
namespace Beep.OilandGas.Web.Services;
public sealed partial class AccountingServiceClient
{
    public async Task<CompanySalesPaymentReviewSource> GetCompanySalesPaymentReviewAsync(string id)
    {PaymentIdentity(id);var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null)throw new InvalidOperationException("Select the original reviewer company/account.");var value=await _apiClient.GetAsync<CompanySalesPaymentReviewSource>(PaymentRoute+"/payment-review/"+Uri.EscapeDataString(id))??throw new InvalidOperationException("The original payment review is unavailable.");value.Require();var source=value.Current.Ledger;if(snapshot!=_apiClient.CompanySnapshot || source.Company!=snapshot.Selection.Scope || source.ActorUserId!=snapshot.Selection.UserId || value.Original.AR_PAYMENT_ID!=id)throw new InvalidOperationException("The original payment reviewer context changed.");return CompanyInventorySourceReview.Copy(value);}
    public async Task<AR_PAYMENT> RecordCompanySalesPaymentReviewAsync(CompanySalesPaymentReviewCommand command)
    {command=CompanyInventorySourceReview.Copy(command);command.Require();var snapshot=_apiClient.CompanySnapshot;var source=command.Review.Current.Ledger;if(snapshot.Selection is null || source.Company!=snapshot.Selection.Scope || source.ActorUserId!=snapshot.Selection.UserId)throw new InvalidOperationException("Return to the original payment reviewer company/account.");var row=await _apiClient.PostAsync<CompanySalesPaymentReviewCommand,AR_PAYMENT>(PaymentRoute+"/payment-decisions",command)??throw new InvalidOperationException("The original payment disposition is unconfirmed.");if(snapshot!=_apiClient.CompanySnapshot || JsonSerializer.Serialize(CompanySalesPaymentReviewProof.Require(row).Intent.Restore())!=JsonSerializer.Serialize(command))throw new InvalidOperationException("The exact original reviewer command/context changed.");return CompanyInventorySourceReview.Copy(row);}
    public async Task<CompanySalesPaymentReviewRecovery> GetCompanySalesPaymentReviewRecoveryAsync(string id)
    {PaymentIdentity(id);var snapshot=_apiClient.CompanySnapshot;if(snapshot.Selection is null)throw new InvalidOperationException("Select the original payment reviewer company/account.");var value=await _apiClient.GetAsync<CompanySalesPaymentReviewRecovery>(PaymentRoute+"/payment-review-recovery/"+Uri.EscapeDataString(id))??throw new InvalidOperationException("The original payment reviewer recovery is unavailable.");value.Require();if(snapshot!=_apiClient.CompanySnapshot || value.Company!=snapshot.Selection.Scope || value.ActorUserId!=snapshot.Selection.UserId || value.PaymentId!=id)throw new InvalidOperationException("The original payment reviewer recovery context changed.");return CompanyInventorySourceReview.Copy(value);}
}
